import React, { createContext } from "react";
import { useInterpret } from "@xstate/react";
import { promiseMachine } from "./MattsMachine";

export const MattsMachineGlobalStateContext = createContext({});

export const MattsMachineGlobalStateProvider = (props) => {
  const promiseService = useInterpret(promiseMachine);

  return (
    <MattsMachineGlobalStateContext.Provider value={{ promiseService }}>
      {props.children}
    </MattsMachineGlobalStateContext.Provider>
  );
};

import logo from './logo.svg';
import './App.css';

function App() {
  return (
    <div className="App">
      <header className="App-header">
        <img src={logo} className="App-logo" alt="logo" />
        <p>
          Edit <code>src/App.js</code> and save to reload.
        </p>
        <a
          className="App-link"
          href="https://reactjs.org"
          target="_blank"
          rel="noopener noreferrer"
        >
          Learn React
        </a>
      </header>
    </div>
  );
}

export default App;

import React, { useContext } from "react";
import { MattsMachineGlobalStateContext } from "./MattsMachineGlobalState";
import { useSelector } from "@xstate/react";

const pendingSelector = (state) => {
  return state.matches("pending");
};

const rejectedSelector = (state) => {
  return state.matches("rejected");
};

const reslovedSelector = (state) => {
  return state.matches("resloved");
};

const MattsMachineControl = (props) => {
  const globalServices = useContext(MattsMachineGlobalStateContext);
  const isPending = useSelector(globalServices.promiseService, pendingSelector);
  const isRejected = useSelector(
    globalServices.promiseService,
    rejectedSelector
  );
  const isResolved = useSelector(
    globalServices.promiseService,
    reslovedSelector
  );

  // const [state, send] = useMachine(promiseMachine);
  const { send } = globalServices.promiseService;
  return (
    <div>
      {/** You can listen to what state the service is in */}
      {isPending && <p>Loading...</p>}
      {isRejected && <p>Promise Rejected</p>}
      {isResolved && <p>Promise Resolved</p>}
      <div>
        {/** You can send events to the running service */}
        <button onClick={() => send("RESOLVE")}>Resolve</button>
        <button onClick={() => send("REJECT")}>Reject</button>
      </div>
    </div>
  );
};

export default MattsMachineControl;

import { createMachine } from "xstate";

const promiseMachine = createMachine({
  id: "promise",
  initial: "pending",
  states: {
    pending: {
      on: {
        RESOLVE: { target: "resolved" },
        REJECT: { target: "rejected" },
      },
    },
    resolved: {
      type: "final",
    },
    rejected: {
      type: "final",
    },
  },
});

export { promiseMachine };

import React from "react";
import ReactDOM from "react-dom";
import "./index.css";
import App from "./App";
import MattsMachineControl from "./MattsMachineControl";
import reportWebVitals from "./reportWebVitals";
import Resolver from "./Resolver";
